import {createRequire} from 'node:module';
import {readFile,writeFile,mkdir,readdir,copyFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
const modulePath=process.argv[2]??'sharp',batch=Number(process.argv[3]??121),initial=process.argv[4]==='initial',sharp=createRequire(import.meta.url)(modulePath),root='art/review/web-v3',folder=root+'/gameplay-seats-calibration-20261026';
await mkdir(folder,{recursive:true});
const previous=await readFile(folder+'/coverage.json','utf8').then(JSON.parse).catch(()=>null);
if(previous&&previous.batch!==batch){await mkdir(folder+'/history-'+previous.batch,{recursive:true});for(const f of await readdir(folder,{withFileTypes:true}))if(f.isFile())await copyFile(folder+'/'+f.name,folder+'/history-'+previous.batch+'/'+f.name,1).catch(e=>{if(e.code!=='EEXIST')throw e;});}
const sourceNames={idle:['25-gameplay-selection-idle-v2.png'],selected:['26-gameplay-selection-complete-v2.png'],notimer:['14-gameplay-notimer-selection-v4.png'],'play-pending':['19-play-pending-selection-v2.png'],bid:['10-bid.png','10-bid-timer-v3.png'],'bid-pending':['17-bid-pending-v1.png','17-bid-pending-timer-v3.png'],chooser:['11-chooser-inactive-hand-v5.png'],'chooser-pending':['18-chooser-pending-inactive-hand-v5.png'],'dense-idle':['27-dense-hand-idle-v4.png'],'dense-selected':['28-dense-hand-selected-v4.png'],reconnecting:['15-reconnecting-network-v2.png','15-reconnecting-inactive-hand-v3.png'],'session-ended':['16-session-ended-network-v3.png','16-session-ended-v2.png'],'reconnecting-focus':['29-reconnecting-focus-v2.png','29-reconnecting-focus-v3.png'],'session-ended-focus':['30-session-ended-focus-v2.png']};
const layout=JSON.parse(await readFile('art/runtime/web-v3/gameplay-seats-v1/layout-v2.json','utf8')),sha=async p=>createHash('sha256').update(await readFile(p)).digest('hex'),reports=[];
