 if(initial&&state!=='idle')continue;const tall=profile==='portrait',width=tall?390:1672,height=tall?694:941,actualBatch=batch>=126?(tall&&state.startsWith('bid')?126:124):batch,prefix=`${actualBatch}-seats-${state}-${profile}-20261026`,record=JSON.parse(await readFile(root+'/'+prefix+'.json','utf8')),capture=folder+`/${state}-${profile}-chrome.png`;
 if(record.profile!==profile||record.viewport[0]!==width||Math.abs(record.viewport[1]-height)>1||Math.abs(record.dpr-1)>.001||record.fonts!=='loaded'||!record.images||record.seats.length!==6||record.seats.some(s=>!s.asset.includes('/gameplay-seats-v1/'+profile+'-')))throw Error('Wrong capture state '+prefix);
 const stitch=spawnSync(process.execPath,['tools/stitch-web-chrome-tiles.mjs',root+'/'+prefix+'.json',capture,modulePath],{encoding:'utf8'});if(stitch.status)throw Error(stitch.stderr);
 const source=`art/mockups/web-v3/${tall?'portrait/':''}${names[tall?1:0]??names[0]}`,out=folder+`/${state}-${profile}`;
